def horiz_sym(c):
    ys=[p[0] for p in c]; xs=[p[1] for p in c]
    h_=max(ys)-min(ys)+1; w_=max(xs)-min(xs)+1
    S={(y-min(ys),x-min(xs)) for y,x in c}
    return all((r,w_-1-c2) in S for r,c2 in S)
